#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    long long sum = 0;
    int min = 0, max = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        sum += x;
        if (i == 0 || x < min) {
            min = x;
        }
        if (i == 0 || x > max) {
            max = x;
        }
    }
    printf("%lld %d %d %.2f\n", sum, min, max, (double)sum / n);
    return 0;
}

