#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    long long prev = 0, cur = 1;
    for (int i = 1; i <= n; i++) {
        if (i > 1) {
            printf(" ");
        }
        printf("%lld", cur);
        long long next = prev + cur;
        prev = cur;
        cur = next;
    }
    printf("\n");
    return 0;
}

