#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int count = 0;
    for (int d = 1; d <= n; d++) {
        if (n % d == 0) {
            if (count > 0) {
                printf(" ");
            }
            printf("%d", d);
            count++;
        }
    }
    printf("\n%d\n", count);
    return 0;
}

